  if (s.startsWith('Upper Primary/Secondary')) return 'upper_primary_secondary';
  if (s.startsWith('Senior Secondary')) return 'senior_secondary_pgt';
  return null; // ambiguous/ungrounded — keep every bullet, the safest default
